{
  "summary": "Yes, the agreement grants ISA an exclusive license to market, sell, and distribute Rubicon's offerings in the United States, while restricting Rubicon from entering into additional distribution agreements with third parties in the U.S. without ISA's prior written approval.",
  "evidence": [
    {
      "passage_id": 1,
      "quote": "Rubicon desires to engage ISA as Rubicon's exclusive agent in the United States for the purposes of reselling Rubicon's software and services"
    },
    {
      "passage_id": 5,
      "quote": "Rubicon hereby grants to ISA during the Term (as defined below) and subject to the exclusions described in 2.4 below an exclusive, non-transferable license in the United States to market, sell, use, display, perform, sublicense and distribute the Rubicon Offerings"
    },
    {
      "passage_id": 2,
      "quote": "Rubicon agrees not to enter into any additional agreement to sell Rubicon Offerings or Documentation or additional distribution arrangements with third parties in the United States from the date hereof without the prior written approval of ISA"
    }
  ]
}
